<script setup>
import { computed, ref, watch } from 'vue'
import { FileText, LoaderCircle, Plus, Trash2 } from 'lucide-vue-next'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../ui/dialog'
import { Button } from '../ui/button'
import InfoHint from './InfoHint.vue'
import LoadingSkeleton from './LoadingSkeleton.vue'
import { api } from '../../workspace/api'
const props = defineProps({ project: { type: Object, default: null }, open: Boolean, theme: { type: String, default: 'light' } })
const emit = defineEmits(['update:open','updated'])
const current = ref(null), models = ref([]), loading = ref(false), busy = ref(''), error = ref(''), saved = ref('')
const instructions = ref(''), preferredModel = ref(''), noteName = ref(''), noteText = ref('')
const fileInput = ref(null)
const sourceCharacters = computed(() => (current.value?.sources || []).reduce((sum, source) => sum + source.text.length, 0))
const missingModel = computed(() => preferredModel.value && !models.value.some(model => model.id === preferredModel.value))
function hydrate(value,resetPreferences=true){current.value=value;if(resetPreferences){instructions.value=value.instructions||'';preferredModel.value=value.preferred_model||''}emit('updated',value)}
async function load(){if(!props.project?.id)return;loading.value=true;error.value='';saved.value='';try{const results=await Promise.allSettled([api('/api/workspace/projects/'+props.project.id),api('/api/workspace/models')]);if(results[0].status==='rejected')throw results[0].reason;hydrate(results[0].value);models.value=results[1].status==='fulfilled'?results[1].value.models:[]}catch(err){error.value=err.message}finally{loading.value=false}}
watch(()=>[props.open,props.project?.id],([open])=>{if(open)load()},{immediate:true})
async function savePreferences(){busy.value='preferences';error.value='';saved.value='';try{hydrate(await api('/api/workspace/projects/'+current.value.id,{method:'PATCH',body:{instructions:instructions.value,preferred_model:preferredModel.value}}));saved.value='Project preferences saved.'}catch(err){error.value=err.message}finally{busy.value=''}}
async function addSource(name,text){if(!current.value)return;const body={name,text};if(new TextEncoder().encode(JSON.stringify(body)).length>30000)throw new Error('This source exceeds the 30 KB request limit. Shorten or split it.');hydrate(await api('/api/workspace/projects/'+current.value.id+'/sources',{method:'POST',body}),false)}
async function saveNote(){busy.value='source';error.value='';saved.value='';try{await addSource(noteName.value,noteText.value);noteName.value='';noteText.value='';saved.value='Source saved to this project.'}catch(err){error.value=err.message}finally{busy.value=''}}
async function readFiles(event){const files=[...(event.target.files||[])];busy.value='files';error.value='';saved.value='';try{for(const file of files){if(!/\.(md|txt|csv|json)$/i.test(file.name))throw new Error('Choose Markdown, text, CSV or JSON files.');if(file.size>100000)throw new Error(file.name+' is too large. Use an excerpt of up to 24,000 characters.');const text=await file.text();if(text.length>24000||text.includes('\0'))throw new Error(file.name+' exceeds the text limit or contains unsupported binary data.');await addSource(file.name,text)}saved.value=files.length?'Project files saved.':''}catch(err){error.value=err.message}finally{busy.value='';event.target.value=''}}
async function removeSource(source){if(!confirm(`Remove ${source.name} from this project? This cannot be undone.`))return;busy.value=source.id;error.value='';saved.value='';try{hydrate(await api('/api/workspace/projects/'+current.value.id+'/sources/'+source.id,{method:'DELETE'}),false);saved.value='Source removed.'}catch(err){error.value=err.message}finally{busy.value=''}}
</script>
<template>
  <Dialog :open="open" @update:open="emit('update:open',$event)"><DialogContent class="ws-overlay project-knowledge-dialog" :data-theme="theme"><DialogHeader class="project-knowledge-header"><DialogTitle>{{ current?.name || project?.name || 'Project' }}</DialogTitle><DialogDescription>Instructions, model and saved knowledge.</DialogDescription></DialogHeader>
    <div class="project-knowledge-body"><LoadingSkeleton v-if="loading" class="ws-dialog-skeleton" :lines="4" label="Loading project" /><template v-else-if="current">
      <form class="knowledge-preferences" @submit.prevent="savePreferences"><label>Project instructions<textarea v-model="instructions" rows="4" maxlength="12000" placeholder="Goals, audience, preferred tone or rules for this project" /></label><label>Preferred chat model<select v-model="preferredModel"><option value="">Use the workspace default</option><option v-if="missingModel" :value="preferredModel" disabled>Previously selected model is unavailable</option><option v-for="model in models" :key="model.id" :value="model.id" :disabled="!model.available">{{ model.name }}{{ model.available ? '' : ' · unavailable' }}</option></select></label><Button type="submit" :disabled="!!busy">{{ busy==='preferences'?'Saving…':'Save preferences' }}</Button></form>
      <section class="knowledge-sources"><div class="knowledge-section-heading"><h3>Project knowledge</h3><InfoHint :theme="theme" label="Project source limits">Up to 10 plain-text sources, 24,000 characters per source and 120,000 total. Source requests are limited to 30 KB. Chat receives a bounded excerpt, not necessarily every saved source. Files are read locally and saved as text; no download or code execution occurs.</InfoHint></div><p class="knowledge-note">Save briefs, notes and reference files for project conversations.</p><input ref="fileInput" class="knowledge-file-input" type="file" multiple accept=".md,.txt,.csv,.json" aria-label="Add project text files" @change="readFiles" /><Button type="button" variant="outline" :disabled="!!busy || current.sources.length>=10" @click="fileInput?.click()"><Plus :size="14" />{{ busy==='files'?'Adding files…':'Add text files' }}</Button>
        <div v-for="source in current.sources" :key="source.id" class="knowledge-source"><FileText :size="17" /><details><summary>{{ source.name }}</summary><pre>{{ source.text }}</pre></details><Button type="button" variant="ghost" size="icon" :disabled="!!busy" :aria-label="'Remove '+source.name" @click="removeSource(source)"><Trash2 :size="15" /></Button></div><p v-if="!current.sources.length" class="knowledge-empty">No project sources yet.</p><p v-if="sourceCharacters>24000" class="knowledge-note">Saved knowledge exceeds the chat context window.<InfoHint :theme="theme" label="How project context is bounded">Chat reads relevant sources in bounded sections. More saved text does not mean the model has read it all. Ask about a specific source when details matter.</InfoHint></p>
      </section>
      <form class="knowledge-add-note" @submit.prevent="saveNote"><h3>Add a note</h3><label>Source name<input v-model="noteName" required maxlength="160" placeholder="Product brief or research notes" /></label><label>Text<textarea v-model="noteText" required maxlength="24000" rows="5" placeholder="Paste the context you want to keep with this project" /></label><Button type="submit" :disabled="!!busy || current.sources.length>=10">{{ busy==='source'?'Saving…':'Save note' }}</Button></form>
    </template><p v-if="error" class="knowledge-error" role="alert">{{ error }}</p><p v-if="saved" class="knowledge-saved" role="status">{{ saved }}</p></div>
  </DialogContent></Dialog>
</template>
<style scoped>
:global(.project-knowledge-dialog){width:min(720px,calc(100vw - 32px));max-width:720px!important;max-height:90dvh;display:flex!important;flex-direction:column;gap:0!important;padding:0!important;overflow:hidden;border:1px solid var(--line)!important;border-radius:20px!important;background:var(--panel)!important;color:var(--text)!important}.project-knowledge-header{flex-shrink:0;padding:24px 28px;border-bottom:1px solid var(--line)}.project-knowledge-body{overflow:auto;min-height:0;padding:26px 28px}.knowledge-preferences,.knowledge-add-note{display:grid;gap:19px}.knowledge-preferences label,.knowledge-add-note label{display:grid;gap:9px;font-size:13px;font-weight:550}.knowledge-preferences textarea,.knowledge-preferences select,.knowledge-add-note input,.knowledge-add-note textarea{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 12px;background:var(--panel);color:var(--text);font:inherit;font-size:13px;line-height:1.7}.knowledge-preferences textarea,.knowledge-add-note textarea{resize:vertical;min-height:100px;max-height:300px}.knowledge-preferences button,.knowledge-add-note button,.knowledge-sources>button{justify-self:start;cursor:pointer}.knowledge-sources{display:grid;gap:15px;margin:28px 0;padding:26px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.knowledge-section-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.knowledge-section-heading h3,.knowledge-add-note h3{font-size:15px;font-weight:550;margin:0}.knowledge-note,.knowledge-empty{font-size:12px;line-height:1.8;color:var(--muted);margin:0}.knowledge-file-input{display:none}.knowledge-source{display:flex;gap:11px;align-items:flex-start;padding:14px;border:1px solid var(--line);border-radius:11px}.knowledge-source>svg{margin-top:3px;color:var(--muted);flex-shrink:0}.knowledge-source details{flex:1;min-width:0}.knowledge-source summary{font-size:13px;cursor:pointer;overflow-wrap:anywhere;line-height:1.8}.knowledge-source pre{font-family:inherit;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;color:var(--muted);margin:12px 0 0}.knowledge-source button{width:28px;height:28px;color:var(--muted);flex-shrink:0;cursor:pointer}.knowledge-error,.knowledge-saved{margin:18px 0 0;font-size:12px;line-height:1.8}.knowledge-error{color:var(--no,#b84850)}.knowledge-saved{color:var(--text)}.knowledge-loading{display:flex;align-items:center;justify-content:center;gap:10px;min-height:200px;color:var(--muted);font-size:13px}.project-knowledge-body input:focus-visible,.project-knowledge-body textarea:focus-visible,.project-knowledge-body select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:480px){.project-knowledge-header{padding:23px 21px}.project-knowledge-body{padding:23px 21px}}
</style>
